﻿// Tip: Find more about JS SDK at https://github.com/kontent-ai/sync-sdk-js
import { getSyncClient } from "@kontent-ai/sync-sdk-js";
import { writeFile } from "fs/promises";

// Create a client with public API access
const client = getSyncClient("your-environment-id").publicApi().create();

// Sync changes using the continuation token
const { success, responses, lastContinuationToken, error } = await client
  .sync("stored-continuation-token")
  .toAllPromise();

if (!success) {
  // Handle sync error
  console.error("Failed to sync changes:", error.message);
  return;
}

// Process all responses
for (const response of responses) {
  const { items, types, languages, taxonomies } = response.payload;
  // ... handle the changes
}

// Store the last continuation token in persistent storage (fs, db, etc.) for future sync operations
await writeFile("syncApiToken", lastContinuationToken, "utf8");

// For other means of creating a client, see https://github.com/kontent-ai/sync-sdk-net#quick-start
await using var client = SyncClientBuilder
    .WithOptions(builder => builder
        .WithEnvironmentId("your-environment-id")
        .UsePreviewApi("your-preview-api-key")
        .Build())
    .Build();

// Gets a page of changes since the last stored sync token.
var result = await client.GetDeltaAsync("your-sync-token");
if (!result.IsSuccess)
{
    throw new InvalidOperationException(result.Error?.Message ?? "Sync failed.");
}

var delta = result.Value;
var syncItems = delta.Items;
var syncTypes = delta.Types;
var syncTaxonomies = delta.Taxonomies;
var syncLanguages = delta.Languages;

// Persist this token and use it in the next synchronization call.
string? nextSyncToken = result.SyncToken;
